import fs from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {chromium} from 'playwright';
import {PDFDocument} from 'pdf-lib';

const root=process.cwd(),out=path.join(root,'deliverables');
await fs.mkdir(out,{recursive:true});
const meta=JSON.parse(await fs.readFile('docs/academic-metadata.json','utf8'));
const unit=JSON.parse(await fs.readFile('deliverables/evidence/vitest.json','utf8'));
const browserTests=JSON.parse(await fs.readFile('deliverables/evidence/playwright.json','utf8'));
const captures=JSON.parse(await fs.readFile('deliverables/evidence/screenshots.json','utf8'));
const lock=JSON.parse(await fs.readFile('package-lock.json','utf8'));
if(unit.numFailedTests||browserTests.stats.unexpected)throw new Error('Hasil pengujian belum lulus.');
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const p=s=>`<p>${s}</p>`;
const ul=rows=>`<ul>${rows.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const table=(heads,rows)=>`<table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const fig=(name,caption,cls='')=>`<figure><img class="screen ${cls}" src="screenshots/${name}.png" alt="${esc(caption)}"/><figcaption>${caption}. Sumber: tangkapan aplikasi lokal, data demo fiktif, ${captures.date}.</figcaption></figure>`;
const formula=s=>`<div class="formula">${s}</div>`;
const note=s=>`<aside>${s}</aside>`;
const logo='<svg viewBox="0 0 30 34" width="38" height="43" fill="none"><path d="M5 5v10c0 8 20 2 20 13M25 5v10c0 8-20 2-20 13" stroke="currentColor" stroke-width="3.2"/><circle cx="5" cy="4" r="3" fill="currentColor"/><circle cx="25" cy="4" r="3" fill="currentColor"/></svg>';
const pages=[];
function sheet(chapter,title,body,cls=''){pages.push({chapter,title,body,cls});}
function diagram(nodes,edges,height=440){return `<svg class="diagram" viewBox="0 0 640 ${height}" xmlns="http://www.w3.org/2000/svg" role="img"><defs><marker id="arrow${pages.length}" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8Z" fill="#555"/></marker></defs>${edges.map(([a,b,label])=>{const x=nodes[a],y=nodes[b],x1=x[0]+x[2]/2,y1=x[1]+x[3],x2=y[0]+y[2]/2,y2=y[1];return `<path d="M${x1} ${y1}L${x2} ${y2}" fill="none" stroke="#888" stroke-width="1.5" marker-end="url(#arrow${pages.length})"/>${label?`<text x="${(x1+x2)/2+5}" y="${(y1+y2)/2}" font-size="12">${esc(label)}</text>`:''}`;}).join('')}${nodes.map(([x,y,w,h,label])=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#f4f4f3" stroke="#ccc"/><text x="${x+w/2}" y="${y+h/2}" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-size="14">${label.split('|').map((s,i,a)=>`<tspan x="${x+w/2}" dy="${i?20:-(a.length-1)*10}">${esc(s)}</tspan>`).join('')}</text>`).join('')}</svg>`;}
async function walk(dir){const entries=await fs.readdir(dir,{withFileTypes:true});let found=[];for(const e of entries){const file=path.join(dir,e.name);if(e.isDirectory())found.push(...await walk(file));else found.push(file.replaceAll('\\','/'));}return found;}
const files=[...await walk('src'),...await walk('e2e'),'package.json','tsconfig.json','vite.config.ts','playwright.config.ts','eslint.config.js','index.html','.gitignore','.github/workflows/ci.yml','public/_redirects','start-local.ps1','scripts/inspect-layout.mjs','scripts/capture-academic.mjs','scripts/check-mobile-import.mjs'].sort();
const sources=await Promise.all(files.map(async file=>{const text=await fs.readFile(file,'utf8');return {file,text,lines:text.split(/\r?\n/).length,sha256:createHash('sha256').update(text).digest('hex')};}));
const sourceMap=new Map(sources.map(x=>[x.file,x]));
function excerpt(file,marker,count=25){const src=sourceMap.get(file);const lines=src.text.split(/\r?\n/);let start=marker?lines.findIndex(x=>x.includes(marker)):0;if(start<0)throw new Error(`Penanda cuplikan tidak ditemukan: ${file} ${marker}`);return `<p class="file-label">${esc(file)} · baris ${start+1}–${Math.min(start+count,lines.length)}</p><pre class="snippet">${lines.slice(start,start+count).map((x,i)=>`<span class="code-line"><i>${start+i+1}</i>${esc(x)||' '}</span>`).join('')}</pre>`;}
const npmVersion=name=>lock.packages[`node_modules/${name}`]?.version??'lihat package-lock.json';
const repo=meta.github?`<a href="${esc(meta.github)}">${esc(meta.github)}</a>`:'Belum tersedia. Repositori publik baru menunggu pembuatan melalui akun GitHub pengguna.';

sheet('SAMPUL','Laporan Perancangan dan Implementasi WhatIf',`<div class="cover"><p class="cover-kicker">LAPORAN TUGAS KULIAH</p><h1>PERANCANGAN DAN IMPLEMENTASI<br/>APLIKASI WEB WHATIF</h1><h2>Simulasi dan Prediksi Pendukung<br/>Keputusan Bisnis Usaha Kecil</h2><img class="campus-logo" src="logo-iteba.png" alt="Logo Institut Teknologi Batam"/><div class="brand">${logo}<strong>WhatIf</strong></div><p>Disusun untuk mata kuliah<br/><b>${esc(meta.course)}</b></p><p>Dosen pengampu:<br/>${esc(meta.lecturer)}</p><p>Disusun oleh:<br/><b>${esc(meta.name)}</b><br/>NIM ${esc(meta.nim)}</p><div class="cover-bottom"><b>PROGRAM STUDI ${esc(meta.program.toUpperCase())}</b><br/><b>${esc(meta.university.toUpperCase())}</b><br/>${esc(meta.year)}</div></div>`,'cover-page');
sheet('BAGIAN AWAL','Abstrak',p('Pemilik usaha kecil perlu mempertimbangkan hubungan antara harga, permintaan, biaya, kapasitas, persediaan, dan ketersediaan kas sebelum menjalankan perubahan bisnis. Perhitungan terpisah dapat menyulitkan pemilik dalam membandingkan konsekuensi beberapa pilihan. WhatIf dikembangkan sebagai aplikasi web pendukung keputusan yang menggabungkan simulasi bersyarat, perkiraan pesanan dari riwayat, serta evaluasi hasil keputusan dalam antarmuka sederhana berbahasa Indonesia.')+p('Pengembangan menerapkan pendekatan iteratif dengan React, TypeScript, Vite, komponen antarmuka modular, validasi Zod, dan penyimpanan LocalStorage. Model menghitung keuntungan operasional, batas aman jumlah pesanan, penggunaan kapasitas, dampak stok, serta proyeksi kas. Forecasting membandingkan tiga metode acuan menggunakan pengujian bergulir terhadap catatan sebelumnya. Keputusan yang mulai diuji menyimpan salinan kondisi awal agar evaluasi berikutnya tetap memakai acuan historis.')+p(`Verifikasi lokal menunjukkan ${unit.numPassedTests} dari ${unit.numTotalTests} tes unit/formulir dan ${browserTests.stats.expected} tes browser lulus pada bukti pengujian yang dilampirkan. Pemeriksaan tampilan mencakup desktop, tablet, dan ponsel. Hasil tersebut menunjukkan fungsi yang diuji bekerja pada lingkungan pengujian, bukan ukuran ketepatan prediksi pasar atau hasil survei pengguna. Dataset screenshot dan contoh forecast bersifat fiktif. Aplikasi tidak memerlukan akun, backend, maupun API berbayar untuk fungsi intinya.`)+p('<b>Kata kunci:</b> pendukung keputusan, simulasi bisnis, forecasting, usaha kecil, React, interaksi manusia dan komputer.'));
sheet('BAGIAN AWAL','Kata Pengantar',p(`Laporan ini mendokumentasikan perancangan, implementasi, dan pengujian aplikasi WhatIf sebagai tugas mata kuliah ${esc(meta.course)} pada ${esc(meta.university)}. Pembahasan diarahkan pada hubungan antara fungsi pendukung keputusan dan antarmuka yang dapat dipahami oleh pengguna usaha kecil.`)+p('Dokumen disusun dari pemeriksaan berkas proyek, rumus yang benar-benar digunakan, tangkapan layar aplikasi yang dijalankan, dan bukti pengujian otomatis. Penjelasan membedakan fitur yang tersedia, asumsi model, data contoh, dan keterbatasan implementasi. Lampiran kode lengkap disertakan agar bagian implementasi dapat diperiksa dan dijalankan kembali.')+p('Struktur laporan meliputi pendahuluan, landasan teori, analisis dan perancangan, implementasi, pengujian, serta penutup. Panduan operasional, dokumentasi kode, referensi, dan informasi distribusi proyek melengkapi pembahasan. Identitas akademik mengikuti proyek Pustaka Garden milik penyusun; program studi pada laporan ini ditulis Technopreneur sesuai kebutuhan tugas.')+p('Pengembangan masih dapat dilanjutkan melalui pengujian pengguna nyata, evaluasi forecast pada data operasional, serta integrasi data yang lebih luas. Kritik dan saran dapat dipakai untuk memperbaiki kualitas antarmuka dan model keputusan.')+`<p class="signature">Batam, ${esc(meta.date)}<br/><br/><br/>${esc(meta.name)}<br/>NIM ${esc(meta.nim)}</p>`);
sheet('BAGIAN AWAL','Daftar Isi','__TOC__');
sheet('BAB I · PENDAHULUAN','1.1 Latar Belakang',p('Keputusan usaha sehari-hari sering memiliki konsekuensi yang saling berkaitan. Menaikkan harga dapat meningkatkan kontribusi setiap pesanan, tetapi hasil keseluruhannya bergantung pada jumlah pesanan yang tetap terjadi. Promosi dapat menambah transaksi sambil mengurangi margin. Penambahan tenaga kerja meningkatkan kapasitas sekaligus menambah pengeluaran rutin.')+p('Pemilik usaha juga perlu membedakan keuntungan dengan uang tunai yang tersedia. Pembelian alat mengurangi kas saat dibayar, sementara manfaatnya dapat muncul pada periode berikutnya. Persediaan yang dibeli tidak selalu terjual seluruhnya; keterlambatan pemasok dan bahan kedaluwarsa dapat mengubah hasil operasional. Oleh karena itu, satu angka omzet tidak cukup untuk menjelaskan seluruh konsekuensi keputusan.')+p('WhatIf menyediakan ruang untuk mencoba asumsi sebelum perubahan dijalankan. Pengguna dapat melihat hasil bersyarat, memahami penyebab perubahan, membaca batas aman, dan menyimpan rencana uji. Ketika tersedia riwayat penjualan, aplikasi menambahkan perkiraan pesanan berdasarkan pola data tersebut.')+p('Dari sisi interaksi manusia dan komputer, tantangannya adalah menghadirkan fungsi yang cukup dalam tanpa membebani pengguna dengan banyak menu dan istilah teknis. Antarmuka dipusatkan pada tiga menu serta pertanyaan keputusan yang dekat dengan kegiatan usaha. Rincian tambahan dibuka ketika diperlukan.'));
sheet('BAB I · PENDAHULUAN','1.2 Rumusan Masalah dan Tujuan',table(['Rumusan masalah','Tujuan pengembangan'],[['Bagaimana menghubungkan harga, biaya, permintaan, dan kapasitas?','Membangun mesin simulasi bersama yang terpisah dari komponen tampilan.'],['Bagaimana pengguna memahami hasil tanpa membaca rumus panjang?','Menonjolkan perubahan keuntungan, batas aman, dan penjelasan penyebab.'],['Bagaimana memanfaatkan riwayat tanpa mengarang respons pasar?','Menyediakan metode forecast acuan, pengujian bergulir, dan label sumber asumsi.'],['Bagaimana menilai keputusan setelah dijalankan?','Menyimpan kondisi awal dan membandingkan rencana dengan hasil aktual.'],['Bagaimana menjaga aplikasi mudah digunakan?','Menerapkan tiga menu utama, formulir kontekstual, dan rincian yang dapat dibuka.']])+p('Tujuan umum proyek adalah menghasilkan aplikasi lokal yang dapat dijalankan dan diuji sebagai pendukung keputusan usaha kecil. Tujuan khususnya mencakup pengelolaan profil usaha, penyimpanan skenario, simulasi operasi dan kas, forecast berbasis riwayat, serta pembuatan laporan keputusan.'));
sheet('BAB I · PENDAHULUAN','1.3 Manfaat dan Batasan',ul(['Bagi pemilik usaha: memberi gambaran hubungan antara perubahan keputusan dan konsekuensi finansial/operasional.','Bagi mahasiswa: menjadi penerapan komponen web, pengelolaan state, validasi, pengujian, dan prinsip antarmuka.','Bagi pengembangan berikutnya: menyediakan modul hitung dan sumber kode yang dapat dievaluasi serta diperluas.'])+p('Implementasi difokuskan pada satu profil usaha dengan contoh kedai kopi. Produk dan ekspansi direpresentasikan melalui ekonomi rata-rata pesanan dan kapasitas bersama. Data disimpan pada browser/perangkat yang sama. Aplikasi tidak mencakup autentikasi, sinkronisasi cloud, POS, perpajakan, bunga, atau penyusutan.')+p('Forecast menggunakan riwayat pesanan terlayani. Pengaruh keputusan baru terhadap perilaku pelanggan tetap merupakan asumsi pengguna atau referensi hasil uji, bukan estimasi kausal otomatis. Proyeksi kas menggunakan bulan model 30 hari dengan distribusi transaksi merata. Semua batasan tersebut diperlihatkan dalam aplikasi dan dijelaskan pada dokumentasi.')+note('Seluruh angka bisnis dan dataset pada screenshot laporan merupakan data fiktif untuk demonstrasi. Tidak ada survei pengguna atau data operasional pelanggan yang diklaim telah dikumpulkan.'));
sheet('BAB II · LANDASAN TEORI','2.1 Sistem Pendukung Keputusan',p('Dalam proyek ini, sistem pendukung keputusan dipahami sebagai perangkat yang membantu pemilik membandingkan konsekuensi pilihan berdasarkan data dan asumsi. Pengguna tetap menentukan tujuan dan tindakan. Aplikasi menyajikan hubungan hitung, batas, serta trade-off agar pilihan lebih mudah dinilai.')+table(['Pendekatan','Penerapan pada WhatIf'],[['Simulasi bersyarat','Menghitung hasil apabila harga, biaya, permintaan, atau kapasitas berubah.'],['Forecast berbasis riwayat','Memperkirakan pesanan berikutnya dengan metode acuan dari catatan sebelumnya.'],['Analisis sensitivitas','Menguji hasil ketika permintaan turun atau naik relatif terhadap skenario.'],['Evaluasi keputusan','Membandingkan rencana yang dibekukan dengan total hasil aktual.']])+p('Forecast perlu diperiksa menggunakan data yang belum dilihat model pada langkah pengujian. WhatIf memakai evaluasi bergulir dan membedakan galat uji harian dengan ketepatan horizon penuh. Kisaran sensitivitas pada aplikasi bukan interval probabilitas yang terkalibrasi. Prinsip evaluasi dan ketidakpastian mengacu pada pembahasan forecasting OTexts [4].'));
sheet('BAB II · LANDASAN TEORI','2.2 Teknologi Pengembangan',table(['Teknologi','Versi terpasang','Peran'],[['React',npmVersion('react'),'Komponen dan pembaruan tampilan berdasarkan state.'],['TypeScript',npmVersion('typescript'),'Tipe data dan pemeriksaan statis.'],['Vite',npmVersion('vite'),'Server pengembangan dan build produksi.'],['Tailwind CSS',npmVersion('tailwindcss'),'Fondasi utilitas styling dan desain responsif.'],['React Router',npmVersion('react-router-dom'),'Navigasi halaman pada aplikasi satu halaman.'],['Recharts',npmVersion('recharts'),'Grafik perbandingan dan riwayat.'],['Lucide React',npmVersion('lucide-react'),'Ikon garis minimalis.']])+p('React mendukung pemisahan antarmuka menjadi komponen dan pembaruan berdasarkan state [1]. Vite digunakan untuk pengembangan serta build aset [2]. TypeScript menambahkan pemeriksaan tipe agar struktur profil, skenario, dan hasil lebih konsisten [3]. Versi tabel dibaca langsung dari package-lock.json; versi dokumentasi daring dapat lebih baru.'));
sheet('BAB II · LANDASAN TEORI','2.3 State, Validasi, dan Penyimpanan',table(['Bagian','Implementasi'],[['State aplikasi','Zustand menyimpan dokumen usaha, skenario, riwayat, evaluasi, dan notifikasi.'],['Formulir profil','React Hook Form dengan resolver Zod.'],['Validasi runtime','Skema Zod untuk input dan cadangan JSON [7].'],['Persistensi','LocalStorage pada origin/browser yang digunakan [8].'],['Pencadangan','Ekspor/impor JSON dengan pemeriksaan versi dan struktur.'],['Pengujian','Vitest dan React Testing Library; alur browser melalui Playwright [5][6].']])+p('Pemeriksaan TypeScript berlaku saat pengembangan, sedangkan Zod memeriksa data ketika aplikasi menerima input atau cadangan. Keduanya memiliki fungsi berbeda. Data dari file maupun penyimpanan browser tetap perlu diperiksa pada saat runtime.')+p('LocalStorage bertahan antarsesi pada origin yang sama, namun bukan basis data cloud [8]. Menghapus data browser dapat menghilangkan data lokal. Karena itu aplikasi menyediakan backup, pesan kegagalan penyimpanan, dan penanganan data rusak.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.1 Pendekatan Pengembangan',p('Pengembangan dilakukan secara iteratif. Versi awal mengutamakan kelengkapan perhitungan, kemudian antarmuka disederhanakan berdasarkan arahan pemilik proyek. Penambahan fitur berikutnya mempertahankan struktur tiga menu dan menempatkan analisis rinci di dalam bagian tambahan.')+table(['Tahap','Kegiatan dan hasil'],[['Inisialisasi','Menyiapkan React, TypeScript, Vite, dependensi, konfigurasi, dan struktur modular.'],['Model dasar','Membangun rumus keuntungan, kapasitas, target, serta tes baseline.'],['Antarmuka sederhana','Beranda berbasis pertanyaan, input sesuai keputusan, satu hasil keuntungan utama.'],['Pendalaman keputusan','Batas aman, penyebab perubahan, alternatif, dan pencatatan uji.'],['Data historis','Catatan harian, CSV, forecast acuan dan pengujian bergulir.'],['Perencanaan lanjutan','Kas, stok, alat, produk, kanal, jam buka, dan ekspansi.'],['Verifikasi dan dokumentasi','Tes otomatis, pemeriksaan ukuran layar, screenshot, laporan dan arsip.']])+p('Metode ini merupakan proses rekayasa perangkat lunak untuk tugas proyek. Laporan tidak menyatakan telah melakukan eksperimen pasar atau penelitian kepuasan pengguna.'));
const requirements=[['FR-01','Mengatur profil bisnis dan kondisi awal.','BusinessForm, businessSchema'],['FR-02','Mensimulasikan harga, diskon, dan karyawan.','Simulator, simulate'],['FR-03','Menyimpan, mengubah, menggandakan, dan menghapus skenario.','Scenarios, useStore'],['FR-04','Membandingkan maksimal tiga skenario dengan acuan yang sama.','ComparisonTable, recommendation'],['FR-05','Menghitung target dan batas aman jumlah pesanan.','reverse, decisionAnalysis'],['FR-06','Menjelaskan perubahan keuntungan dan hambatan.','insights, decisionAnalysis'],['FR-07','Mencatat riwayat dan memvalidasi CSV.','History, importSales'],['FR-08','Memperkirakan pesanan dari riwayat yang memenuhi syarat.','forecast'],['FR-09','Menyimpan uji keputusan beserta snapshot acuan.','startDecision, decisionSchema'],['FR-10','Mengevaluasi hasil aktual dan membuat referensi baru.','Decisions'],['FR-11','Menghitung dampak stok, masa simpan, dan pemasok.','inventoryRun'],['FR-12','Menghitung kas, modal awal, piutang, dan tagihan.','cashProjection'],['FR-13','Mendukung alat, campuran produk, kanal, dan ekspansi.','OperationFields, plan schema'],['FR-14','Mengekspor laporan, CSV, dan backup JSON.','Reports, comparisonCSV, download'],['FR-15','Menangani data rusak dan kegagalan penyimpanan.','parseBackup, useStore.commit']];
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.2 Kebutuhan Fungsional',table(['ID','Kebutuhan','Modul'],requirements.slice(0,8)));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.3 Kebutuhan Lanjutan dan Nonfungsional',table(['ID','Kebutuhan','Modul'],requirements.slice(8))+table(['Kebutuhan nonfungsional','Keputusan desain'],[['Kemudahan dipahami','Bahasa Indonesia, istilah dekat dengan usaha, formulir kontekstual.'],['Responsif','Layout menyesuaikan desktop, tablet, dan ponsel.'],['Konsistensi','Satu mesin hitung untuk kartu, tabel, analisis dan laporan.'],['Keterlacakan','Asal asumsi, skema data, snapshot keputusan, dan bukti tes.'],['Aksesibilitas dasar','Label input, fokus keyboard, dialog fokus, reduced motion.']]));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.4 Diagram Use Case',diagram([[215,15,390,55,'WhatIf · Aplikasi pendukung keputusan'],[220,100,370,42,'Mengatur profil bisnis'],[220,165,370,42,'Mencoba dan membandingkan skenario'],[220,230,370,42,'Mencatat riwayat dan melihat forecast'],[220,295,370,42,'Memulai uji dan mengevaluasi hasil'],[220,360,370,42,'Mencetak laporan dan backup'],[5,180,150,90,'Pemilik usaha|pengguna lokal']],[[6,1],[6,2],[6,3],[6,4],[6,5]],430)+p('Aktor utama adalah pengguna/pemilik usaha pada browser lokal. Seluruh fungsi inti dapat dipakai tanpa login. Tidak ada aktor administrator cloud atau penyedia AI yang diperlukan dalam implementasi ini.')+p('Diagram merangkum tujuan pengguna. Implementasi akses tetap menggunakan halaman dan komponen web; diagram ini bukan rancangan otorisasi multi-pengguna.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.5 Arsitektur Aplikasi',diagram([[160,10,320,55,'Antarmuka React|formulir dan navigasi'],[20,110,280,60,'Zustand + Zod|state dan validasi'],[350,110,270,60,'Mesin domain murni|simulate / forecast / planning'],[20,235,280,60,'LocalStorage + JSON|persistensi dan cadangan'],[350,235,270,60,'Hasil dan visualisasi|kartu / grafik / penjelasan'],[160,355,320,55,'Laporan, CSV, dan evaluasi|fungsi pengguna']],[[0,1],[0,2],[1,3],[2,4],[3,5],[4,5]],430)+p('Komponen antarmuka tidak menyimpan angka keuntungan yang di-hardcode. Hasil berasal dari fungsi domain. Pemisahan ini membantu pengujian matematika tanpa browser dan menjaga konsistensi nilai pada berbagai tampilan.')+p('Tidak terdapat server database atau API bisnis eksternal. Build produksi berupa aset statis yang dapat dihosting dengan fallback navigasi SPA.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.6 Alur Aktivitas Pengguna',diagram([[165,5,310,45,'Masukkan kondisi awal bisnis'],[165,80,310,45,'Pilih keputusan dan tujuan'],[10,165,280,55,'Isi asumsi secara manual'],[350,165,280,55,'Gunakan riwayat yang memadai'],[165,265,310,55,'Hitung hasil, batas dan konsekuensi'],[165,355,310,55,'Simpan rencana / mulai uji'],[165,445,310,55,'Isi hasil nyata dan evaluasi']],[[0,1],[1,2,'tanpa riwayat'],[1,3,'dengan riwayat'],[2,4],[3,4],[4,5],[5,6]],520)+p('Pengguna dapat berhenti pada tahap simulasi atau melanjutkan menjadi uji keputusan. Hasil aktual tidak dibuat otomatis dari proyeksi. Catatan aktual diisi pengguna untuk periode yang sama, lalu dibandingkan dengan snapshot yang disimpan.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.7 Rancangan Data Logis',table(['Entitas dokumen','Isi utama','Hubungan'],[['Business','Nama, kategori, produk, harga, biaya, permintaan, kapasitas, hari, biaya tetap.','Satu profil aktif.'],['Scenario','ID, nama, perubahan harga/permintaan, diskon, biaya, karyawan, plan.','Banyak skenario memakai profil aktif.'],['Plan','Kas, stok, kanal, produk, investasi, jam buka, sumber forecast.','Tertanam pada Scenario.'],['Sale','Tanggal, pesanan, harga, biaya, kejadian, catatan.','Satu catatan per tanggal.'],['Decision','Snapshot Business/Scenario, periode, rencana, hasil aktual, status.','Acuan dibekukan pada awal uji.'],['Backup','Versi, Business, Scenario[], Sale[], Decision[], target, stress.','Dokumen JSON yang divalidasi.']])+note('Struktur ini merupakan skema dokumen lokal, bukan ERD tabel SQL. Snapshot pada Decision sengaja disalin agar perubahan profil aktif tidak menulis ulang sejarah keputusan.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.8 Strategi Persistensi dan Validasi',p('Kunci penyimpanan tetap menggunakan whatif:v1. Penambahan history, decisions, dan plan bersifat aditif dengan nilai default netral. Cadangan versi 1 yang lebih lama dapat dibaca tanpa memerlukan data baru yang belum pernah diisi. Versi skema yang tidak didukung ditolak.')+ul(['Nilai uang diperiksa sebagai bilangan Rupiah bulat, terbatas, dan tidak negatif pada input biaya/harga.','Hari operasional dan kapasitas memiliki batas validasi; tanggal kalender dan tanggal ganda diperiksa.','Catatan hari tutup harus berisi nol pesanan. Catatan masa depan tidak diterima sebagai hasil penjualan nyata melalui formulir/CSV.','Penggantian tanggal riwayat yang sudah ada memerlukan konfirmasi. Penghapusan skenario, riwayat, dan evaluasi juga memakai konfirmasi.','Cadangan JSON divalidasi sebelum mengganti state. Kesalahan penyimpanan menghasilkan peringatan agar pengguna mengekspor backup.'])+p('Data yang sudah rusak tidak langsung ditimpa saat aplikasi dibuka. Aplikasi menampilkan kondisi fallback beserta informasi pemulihan. Penulisan berikutnya terjadi melalui tindakan pengguna.'));
sheet('BAB III · ANALISIS DAN PERANCANGAN','3.9 Prinsip Antarmuka dan IMK',table(['Prinsip desain','Penerapan yang dapat diamati'],[['Hierarki informasi','Satu angka keuntungan utama, diikuti perubahan, batas aman, dan penjelasan.'],['Progressive disclosure','Grafik, target, kas, dan asumsi gabungan ditempatkan di bagian yang dapat dibuka.'],['Konsistensi visual','Warna monokrom, garis batas tipis, ikon Lucide, format Rupiah.'],['Hubungan dengan bahasa pengguna','Pilihan “Ubah harga”, “Beri diskon”, “Tambah karyawan”.'],['Umpan balik','Hasil langsung berubah, notifikasi simpan, serta pesan validasi.'],['Pencegahan kesalahan','Batas input, konfirmasi penghapusan/impor, label data contoh.'],['Kontrol pengguna','Reset asumsi, edit ulang, pilih tujuan perbandingan, dan ekspor data.'],['Akses keyboard','Elemen tombol/formulir native, label, fokus tampak, dan pembatasan fokus dialog.']])+p('Penerapan prinsip tersebut didasarkan pada pemeriksaan desain dan pengujian fungsi. Laporan tidak memberikan skor usability karena belum ada pengujian terkontrol terhadap responden manusia.'));
sheet('BAB IV · IMPLEMENTASI','4.1 Struktur Proyek',table(['Direktori/berkas','Tanggung jawab'],[['src/app/','Routing aplikasi.'],['src/pages/','Beranda, simulator, tersimpan, riwayat, evaluasi, laporan, pengaturan.'],['src/components/planning/','Input operasional, panel keputusan, bagian laporan.'],['src/lib/simulation/','Rumus keuangan bersama.'],['src/lib/planning/','Stok, kas, analisis keputusan dan snapshot.'],['src/lib/forecast/','Forecast pesanan dan parser CSV.'],['src/lib/validation/','Skema profil, skenario, plan, riwayat dan keputusan.'],['src/lib/storage/','Zustand, persistensi dan download.'],['src/tests/ dan e2e/','Tes unit/formulir dan tes browser.'],['scripts/','Pemeriksaan visual, capture akademik, dan pembangkit laporan.']])+p(`Lampiran memuat ${sources.length} berkas kode aplikasi, konfigurasi, dan pengujian dengan total ${sources.reduce((a,x)=>a+x.lines,0).toLocaleString('id-ID')} baris menurut pemisahan baris sumber. Berkas dependensi node_modules tidak dianggap sebagai kode yang ditulis untuk proyek.`));
sheet('BAB IV · IMPLEMENTASI','4.2 Model Keuntungan Dasar',formula('Permintaan harian = permintaan awal × (1 + perubahan permintaan / 100)<br/>Kapasitas = kapasitas awal + kapasitas karyawan + penyesuaian operasional<br/>Pesanan bulanan = floor(min(permintaan, kapasitas) × hari operasi)<br/>Omzet = pesanan bulanan × harga akhir<br/>Keuntungan = omzet − biaya variabel − biaya rutin')+table(['Input demo Kopi Senja','Nilai'],[['Harga jual','Rp25.000 / pesanan'],['Biaya variabel','Rp10.000 / pesanan'],['Permintaan dan kapasitas','40 dan 50 pesanan / hari'],['Hari operasional','26 hari / bulan'],['Biaya tetap termasuk gaji lama','Rp9.000.000 / bulan']])+formula('40 × 26 × (25.000 − 10.000) − 9.000.000 = Rp6.600.000')+p('Harga akhir dibulatkan ke Rupiah. Pesanan menggunakan pecahan dalam langkah antara dan dibulatkan ke bawah pada total bulanan. Skenario tambahan dapat mengubah biaya per pesanan, komisi, pemborosan, dan biaya rutin, tanpa memindahkan rumus ke komponen tampilan.'));
sheet('BAB IV · IMPLEMENTASI','4.3 Batas Aman dan Target',formula('Kebutuhan pesanan = ceil((target keuntungan + biaya rutin + biaya pemborosan) / kontribusi per pesanan)')+p('Pada kenaikan harga 10%, harga baru menjadi Rp27.500 dan kontribusi menjadi Rp17.500 jika biaya tetap sama. Untuk mempertahankan keuntungan awal Rp6.600.000, kebutuhan matematis adalah ceil((6.600.000 + 9.000.000) / 17.500) = 892 pesanan. Jumlah awal adalah 1.040, sehingga penurunan volume sekitar 14% masih dapat ditoleransi dalam asumsi tersebut.')+p('Contoh promo diskon 15% dengan biaya pemasaran Rp500.000 membutuhkan 1.432 pesanan untuk menandingi keuntungan awal. Kapasitas awal hanya 1.300 pesanan per bulan. Aplikasi perlu menjelaskan hambatan ini, bukan sekadar memperlihatkan omzet bertambah.')+note('Untuk stok aktif, kebutuhan bersyarat menggunakan biaya pemborosan pada volume saat ini. Pemeriksaan kelayakan juga menjalankan model stok pada permintaan kapasitas penuh. Kebijakan pembelian/expiry dapat mengubah biaya ketika volume berubah; hasil tersebut bukan minimum global yang dioptimalkan.'));
sheet('BAB IV · IMPLEMENTASI','4.4 Forecast Berbasis Riwayat',ul(['Catatan pada/sebelum tanggal acuan saja yang digunakan; catatan masa depan tidak masuk pelatihan.','Hari normal dan tutup dipakai; promo, perubahan harga, stok habis, dan kejadian khusus dipisahkan dari pola normal.','Ambang awal minimal 21 catatan layak serta lima variasi hari dalam minggu. Ini pemeriksaan kelayakan awal, bukan jaminan mutu statistik.','Tiga kandidat: rata-rata sampai empat pengamatan hari sejenis, rata-rata 14 catatan, dan rata-rata tujuh catatan terakhir.','Uji bergulir dimulai setelah 14 catatan dan dibatasi 90 origin terbaru. Setiap prediksi hanya melihat catatan sebelumnya.','Metode dengan MAE terendah dipilih. Rentang sensitivitas menggunakan persentil 80 galat absolut harian.'])+formula('MAE = jumlah |pesanan aktual − pesanan perkiraan| / jumlah pengujian')+p('Galat ini dipakai untuk memilih metode, bukan evaluasi independen atas horizon penuh. Dataset fiktif berulang dapat menghasilkan MAE nol; nilai tersebut tidak membuktikan aplikasi selalu akurat pada usaha nyata. Garis rentang bukan peluang keberhasilan atau interval probabilitas masa depan.'));
sheet('BAB IV · IMPLEMENTASI','4.5 Stok dan Proyeksi Kas',p('Stok diukur sebagai bahan yang cukup untuk satu pesanan model. Proses harian menghapus stok kedaluwarsa, menerima kiriman, melayani pesanan secara FIFO, mencatat kekurangan, lalu memesan jika posisi stok berada di bawah titik pemesanan ulang. Lama tunggu serta jumlah pembelian diisi pengguna.')+p('Biaya keuntungan mengakui bahan yang terjual atau terbuang. Model kas mengakui pembelian bahan ketika dibayar. Kemasan, komisi, dan subsidi dikenakan pada pesanan terlayani; komponen tersebut tidak dianggap sebagai bahan kedaluwarsa. Dengan pemisahan ini, pembelian stok tidak dihitung dua kali sebagai beban keuntungan dan pengeluaran bahan terpakai.')+formula('Kas awal model = saldo awal − investasi awal<br/>Kas hari berikutnya = kas hari ini + penerimaan − pembayaran')+p('Bulan model terdiri atas 30 hari. Transaksi dan biaya rutin disebar merata. Pelanggan dan pemasok dapat memiliki jeda pembayaran. Piutang serta tagihan awal hanya memengaruhi kas, tidak diakui lagi sebagai pendapatan/biaya baru. Nilai di luar horizon tetap tercatat sebagai saldo belum diterima/dibayar.'));
sheet('BAB IV · IMPLEMENTASI','4.6 Snapshot dan Evaluasi Hasil',p('Ketika pengguna memulai uji, aplikasi menyalin profil dan skenario beserta periode serta hasil perkiraannya. Snapshot disimpan terpisah dari profil aktif. Perubahan harga atau biaya pada pengaturan berikutnya tidak mengubah acuan uji yang telah dimulai.')+formula('Keuntungan aktual = omzet aktual − biaya variabel aktual − biaya rutin aktual')+p('Hasil rencana dinormalisasi dengan basis bulan model 30 hari terhadap lama periode uji yang inklusif. Pengguna memasukkan total aktual untuk periode yang sama, beserta catatan konteks. Evaluasi menunjukkan perbedaan keuntungan dan pesanan, lalu dapat menjadi sumber volume referensi pada simulasi berikutnya.')+p('Aplikasi tidak membagi otomatis total aktual menjadi riwayat harian rekaan. Selisih hasil juga tidak dianggap sebagai bukti kausal bahwa satu perubahan saja menyebabkan seluruh perubahan bisnis. Faktor lain dapat dijelaskan pengguna pada catatan evaluasi.'));

const screens=[
['4.7 Beranda Berbasis Pertanyaan','01-beranda','Gambar 4.1. Beranda WhatIf','Beranda menampilkan satu keuntungan dasar dan tiga pilihan utama. Keputusan lain dan tautan riwayat/evaluasi tersedia tanpa menambah menu utama. Kontrol data bisnis mengarah ke pengaturan profil.'],
['4.8 Harga dan Hasil Langsung','02-simulasi-harga','Gambar 4.2. Simulasi kenaikan harga 10% dengan permintaan turun 5%','Pada data demo, 988 pesanan × kontribusi Rp17.500 − biaya tetap Rp9.000.000 menghasilkan keuntungan Rp8.290.000. Formulir dan kartu hasil menggunakan mesin yang sama.'],
['4.9 Batas dan Penjelasan','03-batas-aman','Gambar 4.3. Batas aman jumlah pesanan','Panel menunjukkan kebutuhan 892 pesanan per bulan untuk menjaga keuntungan awal. Penjelasan menyebut syarat biaya dan kapasitas agar pengguna tidak menganggap angka tersebut sebagai ramalan respons pelanggan.'],
['4.10 Promosi','05-promosi','Gambar 4.4. Simulasi promosi dan biaya pemasaran','Diskon, biaya promosi, dan asumsi permintaan diubah secara eksplisit. Pengaturan tambahan mendukung bagian pesanan promo, paket, dan subsidi ongkir. Tambahan omzet tidak otomatis berarti keuntungan lebih tinggi.'],
['4.11 Karyawan dan Kapasitas','06-karyawan','Gambar 4.5. Simulasi tambahan karyawan','Karyawan menambah biaya gaji dan kapasitas layanan. Permintaan tetap merupakan input terpisah. Pada contoh gambar, jumlah pelanggan diasumsikan naik sehingga manfaat tambahan kapasitas dapat dibandingkan dengan biayanya.'],
['4.12 Perbandingan Skenario','08-perbandingan','Gambar 4.6. Perbandingan skenario tersimpan','Pengguna memilih maksimal tiga skenario. Grafik dan tabel memakai kondisi awal yang sama. Tujuan dapat diganti antara keuntungan, kas, permintaan yang tidak terlayani, dan ketahanan terhadap penurunan permintaan.'],
['4.13 Riwayat dan Prediksi','09-prediksi-riwayat','Gambar 4.7. Forecast dari contoh riwayat fiktif','Data CSV diperiksa sebelum disimpan. Forecast menyatakan metode, jumlah catatan, jumlah pengujian, dan galat. Peringatan contoh fiktif ditampilkan. Perkiraan 30 hari dapat digunakan sebagai asumsi simulasi dengan sumber yang tersimpan.'],
['4.14 Persediaan','10-stok','Gambar 4.8. Stok, pemesanan ulang, dan pesanan hilang','Perubahan stok awal, titik pesan ulang, waktu tunggu, dan masa simpan memengaruhi jumlah pesanan yang dapat dilayani. Hasil menunjukkan kekurangan stok dan pemborosan agar biaya operasionalnya terlihat.'],
['4.15 Perjalanan Kas','11-kas','Gambar 4.9. Rencana kas dan persediaan','Bagian ini dibuka ketika diperlukan. Saldo awal, cadangan, waktu pembayaran, dan horizon dapat diubah. Model menampilkan kas terendah dan tambahan cadangan yang diperlukan, serta tabel periode.'],
['4.16 Peralatan','12-peralatan','Gambar 4.10. Investasi atau sewa peralatan','Pembelian alat memengaruhi kas awal. Penghematan biaya dan tambahan kapasitas memengaruhi keuntungan. Balik modal sederhana hanya ditampilkan jika tambahan keuntungan positif dan bergantung pada asumsi yang tetap.'],
['4.17 Campuran Produk','13-produk','Gambar 4.11. Campuran dua produk','Harga dan biaya rata-rata dihitung menggunakan bobot produk. Bobot 1:1 berarti proporsi sama. Model ini menggunakan kapasitas bersama dan tidak memprediksi permintaan setiap SKU secara terpisah.'],
['4.18 Kanal Penjualan','14-kanal','Gambar 4.12. Komisi kanal dan kemasan','Komisi dikenakan pada bagian pesanan yang melalui kanal tersebut. Kemasan merupakan biaya rata-rata per pesanan. Pengguna tetap memasukkan asumsi tambahan pelanggan; aplikasi tidak menganggap kanal baru selalu menaikkan permintaan.'],
['4.19 Evaluasi Keputusan','15-evaluasi','Gambar 4.13. Perbandingan rencana dan hasil aktual fiktif','Formulir evaluasi menggunakan periode dan kondisi awal yang dibekukan. Pada contoh dokumentasi, omzet dan biaya aktual dimasukkan untuk menunjukkan alur evaluasi. Angka tersebut tidak berasal dari usaha nyata.'],
['4.20 Target dan Sensitivitas','16-target-stress','Gambar 4.14. Target keuntungan dan analisis kapasitas','Kebutuhan pesanan dibandingkan dengan kapasitas. Sensitivitas memakai perubahan permintaan pesimistis, dasar, dan optimistis yang dapat diedit. Label tersebut merupakan skenario hipotetis, bukan probabilitas statistik.'],
['4.21 Profil dan Data Lokal','17-profil','Gambar 4.15. Pengaturan profil usaha','Input profil divalidasi sebelum disimpan. Gaji lama termasuk biaya tetap; skenario menghitung gaji karyawan baru secara terpisah. Cadangan dan penjelasan model tersedia di bagian tambahan.'],
['4.22 Laporan Keputusan','18-laporan','Gambar 4.16. Tampilan laporan keputusan','Laporan memakai skenario yang dipilih, asumsi, batas aman, perbandingan, kas, stok, target, sensitivitas, dan evaluasi terkait. CSS cetak menyembunyikan navigasi serta kontrol, lalu browser dapat menyimpan PDF.'],
];
