sheet('BAB V · PENGUJIAN DAN PEMBAHASAN','5.1 Rancangan dan Lingkungan Uji',p('Pengujian menggabungkan tes fungsi murni, interaksi formulir, dan alur browser. Test case dipilih untuk memeriksa hubungan finansial, kondisi batas, persistensi, import/export, serta navigasi. Pemeriksaan visual dilakukan dengan browser pada beberapa ukuran layar.')+table(['Komponen','Bukti/lingkungan'],[['Runtime pembangkit dan proyek',esc(process.version)+' · '+esc(process.platform)+' '+esc(process.arch)],['Vitest',npmVersion('vitest')+' · '+unit.numPassedTests+'/'+unit.numTotalTests+' lulus'],['Playwright',npmVersion('@playwright/test')+' · '+browserTests.stats.expected+' tes sesuai harapan'],['Browser fungsional','Chrome headless; konteks browser terisolasi.'],['Ukuran responsif','1440, 768, dan 390 piksel; capture akademik 1280×900 serta 390×844.'],['Dataset','Profil dan catatan fiktif; bukan transaksi pelanggan.'],['Bukti mesin','evidence/vitest.json, playwright.json, screenshots.json.']])+p('Tes browser melakukan tindakan dan memeriksa keadaan antarmuka. Playwright mendukung isolasi konteks sehingga data tes tidak mengganti penyimpanan pada browser pengguna [5]. Hasil pengujian di bawah berasal dari eksekusi lokal, bukan GitHub Actions.'));
sheet('BAB V · PENGUJIAN DAN PEMBAHASAN','5.2 Hasil Pengujian Unit dan Formulir',table(['Kelompok','Jumlah tes','Status'],unit.testResults.map(r=>[esc(r.name.replaceAll('\\','/').split('/').slice(-2).join('/')),r.assertionResults.length,r.status==='passed'?'Lulus':esc(r.status)]))+p(`Jumlah total: ${unit.numPassedTests} lulus, ${unit.numFailedTests} gagal. Bukti JSON menyimpan nama setiap assertion. Tes mencakup baseline, harga, promosi, gaji, kapasitas, target, kontribusi nol/negatif, volume nol, kas, stok, produk, funnel, CSV, snapshot, dan validasi formulir.`)+p('Persentase tes yang lulus hanya menyatakan hasil kumpulan kasus yang dijalankan. Angka tersebut tidak menunjukkan cakupan seluruh kemungkinan input, kualitas prediksi pada bisnis nyata, keamanan menyeluruh, ataupun skor kemudahan penggunaan.')+note('Aplikasi belum memiliki hasil user acceptance test terkontrol atau tolok ukur performa formal. Pemeriksaan visual dan tes otomatis tidak digantikan menjadi klaim survei pengguna.'));
sheet('BAB V · PENGUJIAN DAN PEMBAHASAN','5.3 Verifikasi Studi Kasus Finansial',table(['Kasus uji','Hasil yang diharapkan','Penjelasan'],[['Baseline','Rp6.600.000','1.040 × Rp15.000 − Rp9.000.000.'],['Harga +10%, permintaan −5%','Rp8.290.000','988 × Rp17.500 − Rp9.000.000.'],['Harga −10%','Rp4.000.000','Volume tetap; kontribusi menjadi Rp12.500.'],['Dua karyawan, permintaan tetap','Rp600.000','Tambahan gaji Rp6.000.000 tidak menambah permintaan.'],['Target Rp15.000.000, baseline','Tidak layak pada kapasitas awal','Perlu 1.600; kapasitas 1.300 pesanan.'],['Alat menghemat Rp1.000/pesanan','Rp7.640.000','Investasi dicatat pada kas, bukan laba operasional.'],['Piutang pelanggan baru tertunda 30 hari','Rp26.000.000 belum diterima','Penerimaan di luar horizon tetap menjadi piutang.'],['Kasus penjualan nol','Rugi sebesar biaya rutin','Margin ditampilkan nol jika omzet nol.']])+p('Nilai pada tabel cocok dengan assertion sumber. Kasus tambahan memastikan stok tidak menciptakan atau menghilangkan unit tanpa pencatatan, dan pembelian tidak dihitung dua kali.'));
function collectBrowser(suites){return suites.flatMap(s=>[...(s.specs??[]).map(x=>({title:x.title,status:x.tests?.[0]?.results?.at(-1)?.status??'unknown'})),...collectBrowser(s.suites??[])]);}
const browserCases=collectBrowser(browserTests.suites);
for(let i=0;i<browserCases.length;i+=7)sheet('BAB V · PENGUJIAN DAN PEMBAHASAN',`5.${i===0?'4':'5'} Hasil Alur Browser${i?' (lanjutan)':''}`,table(['No.','Kasus browser','Hasil'],browserCases.slice(i,i+7).map((x,j)=>[i+j+1,esc(x.title),x.status==='passed'?'Lulus':esc(x.status)]))+p('Bukti mencakup tindakan pengisian, simpan, refresh, perbandingan, konfirmasi, dan pemeriksaan nilai/keadaan yang relevan. Konteks terisolasi menjaga independensi data antar-tes.'));
sheet('BAB V · PENGUJIAN DAN PEMBAHASAN','5.6 Pemeriksaan Visual dan Pembahasan',p('Pemeriksaan dilakukan pada desktop, tablet, serta ponsel emulasi. Halaman kosong dan halaman dengan data sama-sama ditinjau. Bagian operasional tambahan dibuka pada masing-masing ukuran untuk memeriksa pergeseran kolom, pemotongan teks, dan gulir horizontal dokumen.')+table(['Area pemeriksaan','Hasil yang diamati'],[['Navigasi','Tiga menu tetap dapat dipakai pada lebar kecil.'],['Formulir dan hasil','Kolom ditumpuk pada ponsel; ukuran input tetap dapat digunakan.'],['Grafik dan tabel','Grafik mengikuti lebar wadah; tabel panjang menggunakan area gulir.'],['Dialog','Konfirmasi impor/hapus memakai fokus dan tombol eksplisit.'],['Laporan cetak','Navigasi tersembunyi dan isi keputusan tetap muncul.'],['Kelengkapan data','Forecast kosong meminta catatan; tidak muncul tren rekaan.']])+p(`Capture akademik mencatat ${captures.errors.length} kesalahan JavaScript halaman pada proses dokumentasi tersebut. Pernyataan ini terbatas pada alur yang ditangkap. Seluruh screenshot mentah disediakan untuk ditinjau kembali.`));
sheet('BAB V · PENGUJIAN DAN PEMBAHASAN','5.7 Keterbatasan dan Risiko Interpretasi',ul(['Perubahan perilaku pelanggan akibat keputusan baru belum dipelajari sebagai efek kausal otomatis.','Forecast memerlukan data yang layak; 21 catatan hanyalah ambang awal. Galat seleksi harian belum menjadi validasi horizon penuh.','Rata-rata produk dan ekspansi menggunakan kapasitas/ekonomi bersama, bukan model SKU dan cabang terpisah.','Kas memakai bulan model 30 hari serta pembagian merata, belum jadwal transaksi nyata lengkap.','Target dengan stok bersifat kondisional terhadap biaya pemborosan dan kebijakan pembelian.','Data hanya berada pada browser; pengguna perlu cadangan untuk pindah origin/perangkat.','Belum ada autentikasi, sinkronisasi cloud, data pasar langsung, pajak, bunga, atau penyusutan.','Hasil tes otomatis belum menggantikan pengujian pengguna, audit keamanan, atau pengukuran operasional nyata.'])+p('Batasan tersebut menjadi dasar penempatan label sumber, keterangan model, serta anjuran mencoba keputusan dalam skala terbatas.'));
sheet('BAB VI · PENUTUP','6.1 Kesimpulan dan Saran',p('WhatIf berhasil diimplementasikan sebagai aplikasi pendukung keputusan lokal dengan antarmuka tiga menu. Simulasi, analisis batas aman, forecast berbasis riwayat, pencatatan uji, evaluasi aktual, serta perencanaan operasi/kas terhubung melalui modul yang dapat diuji. Pengguna dapat memulai dari asumsi sederhana lalu membuka rincian sesuai kebutuhannya.')+p(`Verifikasi fungsi yang tersedia menunjukkan ${unit.numPassedTests} tes unit/formulir dan ${browserTests.stats.expected} tes browser lulus. Nilai baseline dan studi kasus diperiksa secara matematis. Temuan ini mendukung konsistensi implementasi pada kasus yang diuji, sambil mempertahankan batas interpretasi forecast dan model.`)+p('Pengembangan berikutnya disarankan mencakup pengujian usability dengan pemilik usaha, pengumpulan riwayat operasional yang sah, validasi forecast pada horizon sasaran, serta pencatatan kas berdasarkan tanggal aktual. Integrasi POS, sinkronisasi, dan pemisahan per-produk/per-cabang dapat dipertimbangkan setelah kebutuhan serta biaya operasinya jelas.')+p('Untuk konteks mata kuliah IMK, kontribusi utama proyek adalah penerapan penyajian bertahap, umpan balik langsung, bahasa pengguna, dan kontrol data yang jelas pada persoalan keputusan bisnis.'));
sheet('PANDUAN OPERASIONAL','Menjalankan dan Mendemonstrasikan',ul(['Pasang Node.js 22 atau lebih baru dan buka folder proyek.','Jalankan npm ci, lalu npm run dev -- --port 5173 --strictPort.','Buka http://127.0.0.1:5173/ dan pilih data contoh atau profil sendiri.','Coba kenaikan harga 10%; ubah asumsi pelanggan dan lihat batas aman.','Simpan beberapa skenario, lalu buka Tersimpan untuk memilih perbandingan.','Di Beranda, buka arah bisnis; impor CSV atau catat penjualan harian.','Gunakan data contoh fiktif hanya untuk demonstrasi; baca sumber forecast.','Mulai uji keputusan, lalu isi hasil aktual pada halaman evaluasi.','Buka rincian untuk kas, operasi gabungan, target, atau laporan.','Ekspor backup sebelum membersihkan data browser atau berpindah perangkat.'])+`<pre class="snippet">npm ci\nnpm run dev -- --port 5173 --strictPort\nnpm test\nnpm run lint\nnpm run build\nnpm run test:e2e</pre>`+p('Arsip distribusi tidak menyertakan node_modules atau runtime portable yang berukuran besar. Dependensi dipasang dari package-lock.json. Output produksi dist turut disediakan untuk pemeriksaan build statis.'));
sheet('DISTRIBUSI PROYEK','GitHub, Arsip, dan Reproduksibilitas',p('<b>Akun GitHub:</b> qibytecom. <b>Visibilitas yang diminta:</b> publik.')+p('<b>Repositori:</b> '+repo)+p(esc(meta.githubStatus))+p('Sumber distribusi mencakup kode aplikasi, konfigurasi, tes, dokumentasi, screenshot, bukti pengujian, contoh data fiktif, dan output produksi. File .rar dibuat dengan RAR/WinRAR dan diuji kembali. Arsip tidak memasukkan node_modules, cache, runtime portable, data browser pribadi, maupun kredensial.')+p('Workflow CI disediakan untuk menjalankan lint, unit test, build, dan browser test pada GitHub Actions. Keberadaan workflow belum berarti CI jarak jauh telah berjalan. Bukti tes pada laporan ini berasal dari eksekusi lokal yang tersimpan pada folder evidence.')+p('Manifest sumber berisi jalur, jumlah baris, dan SHA-256. Manifest membantu mencocokkan snapshot kode pada dokumen dengan berkas yang diserahkan. File laporan dan kode lengkap juga tersedia secara terpisah agar mudah dibaca.'));
