sheet('LAMPIRAN','Indeks Lampiran dan Bukti',table(['Lampiran/berkas','Isi'],[['Lampiran_Kode_WhatIf.pdf','Seluruh kode aplikasi, konfigurasi, dan tes pada daftar manifest.'],['screenshots/','Screenshot beresolusi asli, desktop/tablet/ponsel.'],['evidence/vitest.json','Hasil assertion unit dan formulir.'],['evidence/playwright.json','Hasil setiap alur browser.'],['evidence/screenshots.json','Konteks capture dan kesalahan halaman.'],['source-manifest.json','SHA-256 serta jumlah baris sumber.'],['contoh-penjualan-fiktif.csv','Dataset dokumentasi berlabel contoh.'],['Contoh_Laporan_Keputusan_WhatIf.pdf','Contoh PDF yang dicetak dari aplikasi.'],['docs/academic-metadata.json','Identitas dan status distribusi untuk regenerasi.']])+p('Lampiran kode memuat berkas sumber dengan nomor baris. package-lock.json disertakan pada arsip sumber sebagai pengunci dependensi, tetapi tidak dicetak seluruhnya karena berupa metadata paket yang dihasilkan otomatis. Bundel dist dan node_modules tidak diperlakukan sebagai kode aplikasi yang perlu dibaca.'));

const css=`@page{size:A4;margin:25mm 25mm 22mm 30mm}*{box-sizing:border-box}body{margin:0;width:155mm;color:#181818;font:12pt/1.48 'Times New Roman',serif;background:#fff}h1,h2,h3{font-family:Arial,sans-serif;line-height:1.3;margin:0 0 16pt;font-weight:700}h1{font-size:17pt}h2{font-size:14pt}h3{font-size:12pt}p{margin:0 0 11pt;text-align:justify}a{color:inherit;overflow-wrap:anywhere}.sheet{display:flow-root;min-height:242mm;break-after:page}.sheet:last-child{break-after:auto}.chapter{font:9pt/1.4 Arial,sans-serif;letter-spacing:1pt;color:#666;margin-bottom:14pt}.cover{text-align:center;min-height:240mm;display:flex;flex-direction:column;align-items:center;justify-content:space-between}.cover p{text-align:center;margin:0;font-size:12pt}.cover-kicker{letter-spacing:1pt;font:10pt Arial!important}.cover h1{font-size:17pt;margin:15pt 0 5pt}.cover h2{font-size:13pt;font-weight:500;margin:0}.campus-logo{width:64mm;height:auto;margin:12pt 0}.brand{display:flex;align-items:center;gap:10pt;font:27pt Arial,sans-serif}.cover-bottom{font:12pt/1.6 Arial,sans-serif}.signature{margin-top:45pt;text-align:right}table{border-collapse:collapse;width:100%;font:10pt/1.4 Arial,sans-serif;margin:14pt 0;table-layout:fixed}th,td{border:1px solid #d6d6d6;padding:8pt;vertical-align:top;overflow-wrap:anywhere}th{background:#efefed;font-weight:700;text-align:left}ul,ol{margin:0 0 14pt;padding-left:20pt}li{margin-bottom:9pt}aside,.formula{background:#f2f2f0;padding:13pt;margin:15pt 0;border-left:2pt solid #555;font-size:11pt}.formula{font-family:Arial,sans-serif;font-size:10pt;line-height:1.65}figure{margin:15pt 0}.screen{width:100%;height:114mm;object-fit:cover;object-position:top;border:1px solid #ddd}.screen.contain{object-fit:contain;height:140mm}figcaption{font:9pt/1.4 Arial,sans-serif;color:#555;margin-top:7pt;text-align:center}.mobile-pair{display:flex;gap:12mm;align-items:flex-start}.mobile-pair figure{width:calc(50% - 6mm);margin:0 0 14pt}.mobile-pair img{width:100%;height:auto;border:1px solid #ddd}.diagram{width:100%;max-height:174mm;margin:15pt 0}.file-label{font:9pt Arial,sans-serif;overflow-wrap:anywhere}.snippet{white-space:pre-wrap;overflow-wrap:anywhere;font:8.4pt/1.32 Consolas,'Courier New',monospace;background:#f5f5f4;padding:10pt;margin:12pt 0;border:1px solid #ddd}.code-line{display:block;min-height:1.32em}.code-line i{display:inline-block;width:28pt;color:#999;font-style:normal;user-select:none}.toc-row{display:flex;justify-content:space-between;gap:10pt;border-bottom:1px dotted #bbb;padding:3pt 0;font:9.6pt/1.3 Arial,sans-serif}.toc-row b{font-weight:400}.dense{font-size:11pt;line-height:1.35}.dense p{margin-bottom:8pt}.dense table{font-size:9pt}.dense th,.dense td{padding:6pt}.dense .screen{height:95mm}.code-file{break-before:page}.code-file h2{font-size:13pt}.code-listing{white-space:pre-wrap;overflow-wrap:anywhere;font:8pt/1.28 Consolas,'Courier New',monospace;margin:0}.code-listing .code-line{min-height:1.28em}.code-listing .code-line i{width:29pt}.code-head{font:9pt Arial;margin-bottom:12pt;color:#666}.code-index{columns:2;font:9pt/1.45 Arial}.code-index div{break-inside:avoid;margin-bottom:6pt}.code-cover{break-after:page}body.code-doc{font-size:11pt}code{font-family:Consolas,monospace;font-size:.9em}`;
